import ast
targets={
 'news/src/python/mind_data.py':['MindData.sample_valid_data'],
 'visual-retrieval-colpali/prepare_feed_deploy.py':['float_to_binary_embedding'],
 'visual-retrieval-colpali/src/backend/colpali.py':['SimMapGenerator.should_filter_token'],
 'news/src/python/convert_embeddings_to_vespa_format.py':['convert_user_embeddings','convert_news_embeddings'],
 'news/src/python/create_category_ctrs.py':['write_news_category_ctr_update'],
}
for path,names in targets.items():
    src=open(path,encoding='utf-8').read()
    lines=src.splitlines()
    t=ast.parse(src)
    def walk(n,pre=''):
        for c in ast.iter_child_nodes(n):
            if isinstance(c,(ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef)):
                q=pre+c.name
                if q in names:
                    print(f"=== {path}::{q} {c.lineno}-{c.end_lineno}")
                    print("\n".join(lines[c.lineno-1: c.end_lineno]))
                walk(c,q+'.')
    walk(t)
EOF

